    orbit: DEFAULT_ORBIT_CAMERA, style: resolveLyra3dStyle(), lost: false, disposed: false,
    setStyle(value) { this.style = resolveLyra3dStyle(value); }, setOrbit(value) { this.orbit = value; },
    project(point) { return options.legacyProjection ? { x: this.width / 4 + point.x / 2, y: this.height / 4 + point.y / 2, depth: 200, scale: 2 }
      : projectOrbitPoint(point, this.orbit, this); },
