const meshList = resources => [resources.nodes, resources.nodePick, resources.edges, resources.edgePick];
const sphere = value => value === null ? null : { center: value.center.toArray(), radius: value.radius };
function bytes(array) { return Buffer.from(array.buffer, array.byteOffset, array.byteLength); }
