    assert.equal(mesh.count, count); assert.equal(mesh.type, 'Mesh');
    assert.equal(mesh.geometry, geometries[Math.floor(index / 2)]);
    assert.deepEqual(Object.fromEntries(Object.keys(MATERIALS[index % 2]).map(key => [key, key === 'color' ? mesh.material.color.toArray() : mesh.material[key]])), MATERIALS[index % 2]);
