    assert.equal(matrix.itemSize, 16); assert.equal(matrix.count, count); assert.equal(matrix.normalized, false); assert.equal(matrix.usage, 35044);
    assert.equal(matrix.version, matrixVersion); assert.deepEqual(matrix.updateRanges, []);
    assert.equal(matrix.onUploadCallback, BufferAttribute.prototype.onUploadCallback);
