      assert.equal(color.itemSize, 3); assert.equal(color.count, count); assert.equal(color.normalized, false); assert.equal(color.usage, 35044);
      assert.equal(color.version, colorPolicy[0]); assert.deepEqual(color.updateRanges, colorPolicy[1]);
