for (const route of ['normal', 'staged']) test(`${route} ordinary upload and later sparse/style paint preserve captured versions`, async () => {
  await withLegacy('ordinary', route, fixture => {
    const expected = LIFECYCLE[route]; assertOutput(fixture, expected.initial, [4, 4]);
    for (const mesh of fixture.observed.meshes) mesh.instanceColor.onUploadCallback();
    assertOutput(fixture, expected.uploaded, [4, 4]);
    fixture.engine.setState({ selected: new Set([0, 5]), dimmed: new Set([2]), focus: 2, hover: -1 });
    assertOutput(fixture, expected.sparsePaint, [4, 4]);
    fixture.engine.setStyle({ ...fixture.options.style, palette: ['#103050', '#f0b070'], lineWidth: 3 });
    assertOutput(fixture, expected.stylePaint, [4, 4]);
  });
});

test('prepared ordinary sparse and style paint use existing upload and matrix policies', () => {
  const fixture = prepared(), value = finish(fixture.work); install(fixture, value);
  try {
    for (const mesh of meshList(value.resources)) mesh.instanceColor.onUploadCallback();
    assertOutput(fixture, LIFECYCLE.normal.uploaded, [4, 4]);
    const state = { selected: new Set([0, 5]), dimmed: new Set([2]), focus: 2, hover: -1 };
    value.batch.paint(fixture.view.style, state, [0, 1, 2, 4, 5, 6]);
    assertOutput(fixture, LIFECYCLE.normal.sparsePaint, [4, 4]);
    fixture.view.style = resolveLyra3dStyle({ ...fixture.options.style, palette: ['#103050', '#f0b070'], lineWidth: 3 });
    value.batch.updateTransforms(fixture.view, fixture.data.positions, fixture.presentation.revision);
    value.batch.paint(fixture.view.style, state);
    assertOutput(fixture, LIFECYCLE.normal.stylePaint, [4, 4]);
  } finally { value.batch.dispose(); fixture.work.dispose(); }
});

test('each visual and pick sphere follows its own first submission after camera and position changes', () => {
  const fixture = prepared(), value = finish(fixture.work, 1); install(fixture, value);
  const meshes = meshList(value.resources), flags = ['nodeSubmitted', 'nodePickSubmitted', 'edgeSubmitted', 'edgePickSubmitted'];
  try {
    for (let stage = 0; stage < 5; stage++) {
      fixture.view.orbit = { ...fixture.options.orbit, yaw: 0.4 + stage * 0.2, pitch: -0.1 + stage * 0.1, distance: 500 + stage * 40 };
      const positions = fixture.options.raw.positions.slice(); positions[0] -= 30 * (stage + 1); positions[3] += 20 * (stage + 1); positions[7] += 10 * (stage + 1);
      value.batch.updateTransforms(fixture.view, positions, fixture.presentation.revision + stage + 1);
      assertOutput(fixture, LIFECYCLE.bounds[stage], [4, 4]);
      for (let mesh = 0; mesh <= Math.min(3, stage); mesh++) assert.deepEqual(sphere(meshes[mesh].boundingSphere), LIFECYCLE.bounds[stage].bounds[mesh]);
      if (stage < 4) meshes[stage].onBeforeRender();
      for (let mesh = 0; mesh < 4; mesh++) assert.equal(value.resources[flags[mesh]], mesh <= stage);
    }
    assert.equal(new Set(meshes.map(mesh => mesh.boundingSphere)).size, 4);
  } finally { value.batch.dispose(); fixture.work.dispose(); }
});

test('normal engine exposes its partially initialized ordinary owner before the first live add callback', async () => {
  await observeInstances(async observed => {
    const options = configuration('ordinary'), fixture = harness(options);
    observed.setAdded(name => { if (name === 'nodes') fixture.engine.dispose(); });
    fixture.engine.setData(options.raw, 0);
    try { await fixture.engine.mount({}, fixture.host); }
    catch { /* A closed initialization may reject; native retirement must still be complete. */ }
    finally { fixture.engine.dispose(); }
    assert.equal(observed.meshes.length, 2);
    assert.equal(observed.trace.filter(row => row[0] === 'added' && row[1] === 'nodes').length, 1);
    for (const name of ['nodes', 'nodesPick']) {
      assert.equal(observed.trace.filter(row => row[0] === 'dispose' && row[1] === name).length, 1);
      assert.equal(observed.trace.filter(row => row[0] === 'dispose-material' && row[1] === name).length, 1);
    }
    assert.equal(observed.trace.filter(row => row[0] === 'dispose-geometry').length, 1);
    assert.equal(fixture.view.world.children.length, 0); assert.equal(fixture.view.pickWorld.children.length, 0);
    assert.equal(fixture.view.disposed, true); assert.equal(fixture.engine.positionOf(0), null); assert.equal(fixture.view.tick, undefined);
  });
});

test('prepared construction is inert and rejects invalid budgets, reentry and calls after transfer', () => {
  let reads = 0, guards = 0;
  const watch = new Proxy({}, { get() { reads++; assert.fail('construction read input'); } });
  const inert = createGraphOrdinaryBatchWork(watch, watch, () => { guards++; return true; });
  assert.equal(reads, 0); assert.equal(guards, 0); inert.dispose(); inert.dispose(); assert.throws(() => inert.step(1), invalidState);
  const fixture = prepared();
  try {
    for (const budget of [0, -1, 1.5, NaN, Infinity, Number.MAX_SAFE_INTEGER + 1]) assert.throws(() => fixture.work.step(budget), { name: 'RangeError' });
    const value = finish(fixture.work, 1); value.batch.dispose(); assert.throws(() => fixture.work.step(0), invalidState);
  } finally { fixture.work.dispose(); }
});

test('every cursor cancellation retires exactly all acquired native owners', async () => {
  const control = prepared(); let total = 0, value;
  try { while (!value) { const step = control.work.step(1); total++; if (step.done) value = step.value; } }
  finally { value?.batch.dispose(); control.work.dispose(); }
  for (let stop = 0; stop < total; stop++) {
    const fixture = prepared();
    await acquiredOwners(acquired => disposalLog(released => {
      for (let step = 0; step < stop; step++) assert.equal(fixture.work.step(1).done, false);
      const expected = acquired(); fixture.work.dispose(); assert.equal(released.size, expected.size);
      for (const owner of expected) assert.equal(released.get(owner), 1);
      fixture.work.dispose(); for (const count of released.values()) assert.equal(count, 1);
      assert.throws(() => fixture.work.step(1), invalidState);
    }));
  }
});

test('every stale guard including final transfer retires exactly acquired owners', async () => {
  let total = 0; const control = prepared('ordinary', () => { total++; return true; });
  try { finish(control.work, 1).batch.dispose(); } finally { control.work.dispose(); }
  for (let stop = 1; stop <= total; stop++) {
    let calls = 0; const fixture = prepared('ordinary', () => ++calls !== stop);
    await acquiredOwners(acquired => disposalLog(released => {
      assert.throws(() => finish(fixture.work, 1), { name: 'AbortError' }); assert.equal(calls, stop);
      const expected = acquired(); assert.equal(released.size, expected.size);
      for (const owner of expected) assert.equal(released.get(owner), 1);
      fixture.work.dispose(); assert.throws(() => fixture.work.step(1), invalidState);
    }));
  }
});

test('same-cursor guard reentry is refused and original guard failures survive cleanup failures', () => {
  let work;
  const fixture = prepared('ordinary', () => { assert.throws(() => work.step(0), invalidState); return true; }); work = fixture.work;
  try { finish(work, 1).batch.dispose(); } finally { work.dispose(); }
  const failure = new Error('guard failed'), cleanup = new Error('cleanup failed'); let trigger = false;
  const second = prepared('ordinary', () => { if (trigger) throw failure; return true; });
  disposalLog(released => {
    for (let step = 0; step < 14; step++) assert.equal(second.work.step(1).done, false);
    trigger = true; assert.throws(() => second.work.step(1), error => error === failure);
    assert.ok(released.size > 0); for (const count of released.values()) assert.equal(count, 1);
    second.work.dispose(); assert.throws(() => second.work.step(1), invalidState);
  }, cleanup);
});

for (const [kind, prototype, key] of [['geometry', BufferGeometry.prototype, 'setAttribute'], ['material', Material.prototype, 'setValues'],
  ['instanced mesh', InstancedMesh.prototype, 'updateMorphTargets'], ['bounds', BufferGeometry.prototype, 'computeBoundingSphere']]) {
  test(`${kind} callback boundaries fence disposal, replacement and nested stepping`, async () => {
    let total = 0; const control = prepared();
    withMethod(prototype, key, original => function (...args) { total++; return original.apply(this, args); }, () => {
      try { finish(control.work, 1).batch.dispose(); } finally { control.work.dispose(); }
    });
    assert.ok(total > 0);
    for (let stop = 1; stop <= total; stop++) for (const mode of ['dispose', 'stale', 'reenter']) {
      let calls = 0, current = true; const fixture = prepared('ordinary', () => current);
      await acquiredOwners(acquired => disposalLog(released => withMethod(prototype, key, original => function (...args) {
        const result = original.apply(this, args);
        if (++calls === stop) {
          if (mode === 'dispose') fixture.work.dispose();
          else if (mode === 'stale') current = false;
          else assert.throws(() => fixture.work.step(1), invalidState);
        }
        return result;
      }, () => {
        try {
          if (mode === 'reenter') finish(fixture.work, 1).batch.dispose();
          else assert.throws(() => finish(fixture.work, 1), mode === 'stale' ? { name: 'AbortError' } : aborted);
          const expected = acquired(); assert.equal(released.size, expected.size);
          for (const owner of expected) assert.equal(released.get(owner), 1);
        } finally { fixture.work.dispose(); }
      })));
    }
  });
}

test('preparation never runs constructor identity rows, lazy color fills or full object bounds', () => {
  const fixture = prepared('pickBoundary'); let matrixWrites = 0, value;
  withMethod(InstancedMesh.prototype, 'setMatrixAt', original => function (...args) { matrixWrites++; return original.apply(this, args); }, () =>
    withMethod(InstancedMesh.prototype, 'setColorAt', original => function (...args) { assert.ok(this.instanceColor); return original.apply(this, args); }, () =>
      withMethod(InstancedMesh.prototype, 'computeBoundingSphere', () => function () { assert.fail('object bounds must use the row cursor'); }, () => {
        try {
          for (let calls = 0; calls < 10000; calls++) {
            matrixWrites = 0; const step = fixture.work.step(1);
            // Mesh's superclass count assignment is not the InstancedMesh capacity. Actual native
            // identity-loop writes would occur in a construction step, where initialized rows=0.
            assert.ok(matrixWrites <= 2 * (step.initializedNodes + step.initializedEdges));
            if (step.done) { value = step.value; break; }
          }
          assert.ok(value); for (const mesh of meshList(value.resources)) mesh.onBeforeRender();
        } finally { value?.batch.dispose(); fixture.work.dispose(); }
      })));
});

test('initial row paint uses direct palette lookup without copying or enumerating the palette', () => {
  const fixture = prepared(); fixture.work.dispose();
  const palette = new Proxy(fixture.presentation.style.palette, { get(target, key) {
    assert.ok(key === 'length' || typeof key === 'string' && /^\d+$/.test(key), 'initialization must only read palette rows');
    return Reflect.get(target, key);
  }, ownKeys() { assert.fail('initialization must not enumerate the palette'); } });
  const presentation = { ...fixture.presentation, style: { ...fixture.presentation.style, palette } };
  const work = createGraphOrdinaryBatchWork(fixture.data, presentation);
  try { finish(work, 1).batch.dispose(); } finally { work.dispose(); }
});

test('prepared initialization uses scalar writes without bulk typed-array copies or fills', () => {
  const fixture = prepared('pickBoundary');
  const forbidden = () => function () { assert.fail('prepared rows must not use bulk typed-array writes'); };
  withMethod(Float32Array.prototype, 'set', forbidden, () => withMethod(Float32Array.prototype, 'fill', forbidden, () => {
    try { finish(fixture.work, 1).batch.dispose(); } finally { fixture.work.dispose(); }
  }));
});

test('native submission markers and retirement survive revoked semantic inputs', () => {
  const fixture = prepared(); fixture.work.dispose();
  const semantic = [Proxy.revocable(fixture.data, {}), Proxy.revocable(fixture.presentation.style, {}), Proxy.revocable(fixture.presentation.state, {})];
  const presentation = Proxy.revocable({ ...fixture.presentation, style: semantic[1].proxy, state: semantic[2].proxy }, {});
  semantic.push(presentation);
  const work = createGraphOrdinaryBatchWork(semantic[0].proxy, presentation.proxy);
  let value;
  try {
    value = finish(work, 1);
    const meshes = meshList(value.resources);
    const flags = ['nodeSubmitted', 'nodePickSubmitted', 'edgeSubmitted', 'edgePickSubmitted'];
    assert.deepEqual(Object.keys(value.resources).sort(), ['nodes', 'nodePick', 'edges', 'edgePick', ...flags, 'disposed'].sort());
    const before = meshes.map(mesh => [bytes(mesh.instanceMatrix.array).toString('hex'), bytes(mesh.instanceColor.array).toString('hex'), sphere(mesh.boundingSphere)]);
    value.batch.quiesce(); work.dispose(); for (const proxy of semantic) proxy.revoke();
    for (const [index, mesh] of meshes.entries()) {
      mesh.onBeforeRender();
      for (let flag = 0; flag < 4; flag++) assert.equal(value.resources[flags[flag]], flag <= index);
    }
    assert.deepEqual(meshes.map(mesh => [bytes(mesh.instanceMatrix.array).toString('hex'), bytes(mesh.instanceColor.array).toString('hex'), sphere(mesh.boundingSphere)]), before);
    disposeGraphOrdinaryResources(value.resources); assert.equal(value.resources.disposed, true);
  } finally { value?.batch.dispose(); work.dispose(); }
});

test('resource-only retirement attempts every owner despite failures and quiesce prevents updates', () => {
  const fixture = prepared(), value = finish(fixture.work); install(fixture, value);
  const meshes = meshList(value.resources), owners = [...meshes, ...meshes.map(mesh => mesh.material), meshes[0].geometry, meshes[2].geometry];
  value.batch.quiesce();
  const versions = meshes.map(mesh => [mesh.instanceMatrix.version, mesh.instanceColor.version]);
  const payloads = meshes.map(mesh => [bytes(mesh.instanceMatrix.array).toString('hex'), bytes(mesh.instanceColor.array).toString('hex'), sphere(mesh.boundingSphere)]);
  value.batch.updateTransforms({ ...fixture.view, width: 900 }, fixture.data.positions, 99); value.batch.paint(fixture.view.style, fixture.presentation.state);
  assert.deepEqual(meshes.map(mesh => [mesh.instanceMatrix.version, mesh.instanceColor.version]), versions);
  assert.deepEqual(meshes.map(mesh => [bytes(mesh.instanceMatrix.array).toString('hex'), bytes(mesh.instanceColor.array).toString('hex'), sphere(mesh.boundingSphere)]), payloads);
  const failure = new Error('retirement failed');
  disposalLog(released => {
    assert.throws(() => disposeGraphOrdinaryResources(value.resources), error => error === failure);
    assert.equal(value.resources.disposed, true); assert.equal(released.size, owners.length);
    for (const owner of owners) assert.equal(released.get(owner), 1);
    assert.equal(fixture.view.world.children.length + fixture.view.pickWorld.children.length, 0);
    disposeGraphOrdinaryResources(value.resources); value.batch.dispose(); fixture.work.dispose();
    for (const owner of owners) assert.equal(released.get(owner), 1);
  }, failure);
});

test('parent-removal failures do not skip any ordinary native release', () => {
  const fixture = prepared(), value = finish(fixture.work); install(fixture, value);
  const failure = new Error('parent removal failed');
  try {
    withMethod(Mesh.prototype, 'removeFromParent', original => function () { original.call(this); throw failure; }, () => disposalLog(released => {
      assert.throws(() => disposeGraphOrdinaryResources(value.resources), error => error === failure);
      assert.equal(released.size, 10); for (const count of released.values()) assert.equal(count, 1);
      assert.equal(fixture.view.world.children.length + fixture.view.pickWorld.children.length, 0);
    }));
  } finally { value.batch.dispose(); fixture.work.dispose(); }
});
